// ============================================================
// Image & Category Configuration – MobAtidor
// All image paths relative to /public (originals in public/images).
// Optimised WebP variants are generated by `npm run optimize:images`
// and resolved at render time via ./responsiveImage.ts.
// ============================================================
import { IMAGE_MANIFEST } from './imageManifest'

export interface GalleryImage {
  src: string
  alt: string
  aspectRatio?: 'square' | 'portrait' | 'landscape'
}

export interface Category {
  slug: string
  name: string
  shortName: string
  heading: string
  description: string
  longDescription: string
  galleryTitle: string
  cardImage: string        // image shown on product card
  heroImage?: string       // category page banner (defaults to first gallery image)
  images: GalleryImage[]
}

// Collects every photo of a folder (public/images/<folder>) in numeric order
// (IMG_X_1, IMG_X_2, … IMG_X_10). New photos appear automatically after
// running `npm run optimize:images`.
function folderImages(
  folder: string,
  altPrefix: string,
  aspectRatio: GalleryImage['aspectRatio'],
): GalleryImage[] {
  return Object.keys(IMAGE_MANIFEST)
    .filter((key) => key.startsWith(`images/${folder}/`))
    .sort((a, b) => a.localeCompare(b, 'en', { numeric: true }))
    .map((key, i) => ({ src: `./${key}`, alt: `${altPrefix} – proiect ${i + 1}`, aspectRatio }))
}

